def table(headers,rows):
    return '\n'.join(['| '+' | '.join(map(str,headers))+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(x).replace('|','/').replace('\n',' ') for x in r)+' |' for r in rows])+'\n'
def f(x,d=4):return f'{x:.{d}f}'
def pct(x):return f(x*100,2)
forecast_table=table(['Method','Windows','Days evaluated','Pooled MAE (Rs/day)','Pooled RMSE (Rs/day)','Window MAE mean +/- SD','Window RMSE mean +/- SD'],[[m,v['windows'],v['samples'],f(v['mae'],2),f(v['rmse'],2),f(v['window_mae_mean'],2)+' +/- '+f(v['window_mae_std'],2),f(v['window_rmse_mean'],2)+' +/- '+f(v['window_rmse_std'],2)] for m,v in p['forecast'].items() if m in ['historical_mean','moving_average_14','seasonal_naive_7','proposed']])
