allocation_table=table(['Constraint','Evaluated denominator','Violations'],[[k,n['investment']['grid']['allocations'] if k in ['negative','minimum_allocated','hard_filter'] else n['investment']['grid']['eligible'] if k=='pct_sum_not100' else n['investment']['grid']['n'],v] for k,v in n['investment']['grid']['violations'].items()])
live=initial['llm']['live']+n['llm']['live'];lat=[x['latency_ms'] for x in live]
live_table=table(['Call','Profile','API JSON parse success','Application schema success','Fallback path required','API latency (ms)'],[[i+1,'safe' if not x['cfg'] else 'high volatility' if len(x['cfg'])==1 else 'vulnerable',int(x['api_success']),int(x['schema_success']),int(x['fallback']),f(x['latency_ms'],3)] for i,x in enumerate(live)])
